{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Events & Series</title>
  <meta name="description" content="Gentle, integrative workshops and care series that support whole-person health in {{CITY}}, {{STATE}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav" id="nav">
        <a href="/">Home</a>
        <a href="services.html">Offerings</a>
        <a href="conditions.html">Concerns</a>
        <a href="approach.html">Our Way</a>
        <a href="pricing.html">Investment</a>
        <a href="about.html">Who we are</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Connect</a>
      </nav>
      <button id="navToggle" class="nav-toggle" aria-label="menu">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" id="hero">
      <div class="hero-inner wrap">
        <div class="hero-copy">
          <h1 class="title">A gentler path to whole-person health</h1>
          <p class="subtitle">Join {{BUSINESS_NAME}} — a series of guided events that blend education, movement, and individualized planning to nourish body and mind.</p>
          <div class="hero-ctas">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="#lead">Free workshop</a>
          </div>
          <p class="meta">Led by {{PRACTITIONER_NAME}}, {{CREDENTIALS}} — in-person and virtual options in {{CITY}}, {{STATE}}.</p>
        </div>
        <div class="hero-art" aria-hidden="true">
          <svg class="art" viewBox="0 0 600 400" preserveAspectRatio="xMidYMid slice">
            <defs>
              <linearGradient id="g1" x1="0" x2="1">
                <stop offset="0" stop-color="#f3efe9" />
                <stop offset="1" stop-color="#e8f6f1" />
              </linearGradient>
            </defs>
            <rect width="100%" height="100%" fill="url(#g1)" />
            <g opacity="0.9">
              <circle cx="120" cy="80" r="70" fill="#fffbf2" />
              <path d="M420 320c-40-80-120-120-200-90" stroke="#bfe6d6" stroke-width="20" fill="none" stroke-linecap="round" />
            </g>
          </svg>
        </div>
      </div>
    </section>

    <!-- SOCIAL PROOF -->
    <section class="social-proof wrap">
      <h2 class="section-title">Stories from the circle</h2>
      <div class="testimonials">
        <blockquote class="t">
          "I came for a stress workshop and left with a map for sleep and energy. Practical, kind, and evidence-informed."
          <cite>— L.S., {{CITY}}</cite>
        </blockquote>
        <blockquote class="t">
          "The series helped me see patterns in digestion and mood. The practitioners listened. No miracle promises, just steady progress."
          <cite>— A.K., remote</cite>
        </blockquote>
      </div>
    </section>

    <!-- BENEFITS -->
    <section class="benefits wrap">
      <h2 class="section-title">What you gain</h2>
      <ul class="benefit-list">
        <li>
          <strong>Education that stays</strong>
          <p>Clear, compassionate teaching so you can apply tools at home and work.</p>
        </li>
        <li>
          <strong>Whole-person planning</strong>
          <p>Nutrition, movement, sleep, stress and relationships woven into an individualized plan.</p>
        </li>
        <li>
          <strong>Community rhythm</strong>
          <p>Small cohorts and discussion rounds foster accountability and calm.</p>
        </li>
      </ul>
    </section>

    <!-- PROCESS -->
    <section class="process wrap">
      <h2 class="section-title">Our approach — gentle, structured, measurable</h2>
      <ol class="process-list">
        <li>
          <strong>Intake & listening</strong>
          <p>A thoughtful intake to understand your history, goals, and values.</p>
        </li>
        <li>
          <strong>Co-created plan</strong>
          <p>Short, practical steps and a shared plan to test what helps you most.</p>
        </li>
        <li>
          <strong>Follow-ups & refinement</strong>
          <p>Series check-ins and adjustments informed by tracking and your experience.</p>
        </li>
        <li>
          <strong>Optional labs (educational)</strong>
          <p>When helpful we review evidence-based labs; we explain what tests mean and how they might inform care.</p>
        </li>
      </ol>
    </section>

    <!-- FAQ -->
    <section class="faq wrap">
      <h2 class="section-title">Questions people ask</h2>
      <details>
        <summary>Do you promise cures?</summary>
        <p>We focus on education, resilience, and symptom management. We cannot guarantee cures; our work supports whole-person change over time.</p>
      </details>
      <details>
        <summary>Are events in-person or online?</summary>
        <p>Both. Each event list specifies format; follow-ups may be virtual for convenience.</p>
      </details>
      <details>
        <summary>Can you prescribe medication?</summary>
        <p>Scope depends on licensure. We discuss all options and coordinate with your medical team when needed.</p>
      </details>
    </section>

    <!-- LEAD MAGNET -->
    <section class="lead wrap" id="lead">
      <h2 class="section-title">Join the next series or download the guide</h2>
      <p class="lead-copy">Sign up to receive an intro workshop, quick guide, and early access to upcoming series.</p>
      <form id="leadForm" class="lead-form">
        <label for="name">Name</label>
        <input id="name" name="name" type="text" placeholder="Your name" required>
        <label for="email">Email</label>
        <input id="email" name="email" type="email" placeholder="you@domain.com" required>
        <button class="btn primary" type="submit">Get the guide</button>
        <p class="small">We respect your privacy. No guarantees promised — only education and support.</p>
      </form>
      <div id="leadMsg" class="lead-msg" aria-live="polite"></div>
    </section>

    <!-- CTA -->
    <section class="cta wrap">
      <h3>Ready to begin?</h3>
      <p>Reserve a spot in the next event series or schedule an initial consult with {{PRACTITIONER_NAME}}.</p>
      <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      <p class="muted">Or call us at <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap">
      <p>© {{BUSINESS_NAME}} — nurturing whole-person health in {{CITY}}, {{STATE}}. Practitioner: {{PRACTITIONER_NAME}}, {{CREDENTIALS}}.</p>
      <nav class="footer-nav">
        <a href="about.html">About</a>
        <a href="pricing.html">Pricing</a>
        <a href="contact.html">Contact</a>
      </nav>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
