{"path":"assets/css/styles.css","content":"/* Minimal poetic design — zen_minimal */
:root{
  --bg:#fbfbf9;
  --muted:#6b6b6b;
  --accent:#6fbf9c;
  --accent-2:#8fcad3;
  --card:#ffffff;
  --radius:12px;
  --max-width:1100px;
  --wrap-padding:24px;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#123;background:linear-gradient(180deg,#fbfbf9 0%,#f0f6f4 100%);}
.wrap{max-width:var(--max-width);margin:0 auto;padding:var(--wrap-padding)}
.site-header{backdrop-filter:blur(6px);position:sticky;top:0;background:rgba(255,255,255,0.6);border-bottom:1px solid rgba(0,0,0,0.04)}
.site-header .wrap{display:flex;align-items:center;gap:16px}
.brand{font-weight:700;color:#123;text-decoration:none;padding:12px 0}
.nav{display:flex;gap:12px;margin-left:auto}
.nav a{color:#123;text-decoration:none;padding:10px;border-radius:8px}
.nav a:hover{background:rgba(111,191,156,0.12)}
.nav-toggle{display:none;background:none;border:0;font-size:20px;padding:10px}

.hero{padding:64px 0;position:relative;overflow:hidden}
.hero:before{content:'';position:absolute;inset:0;background:url('/assets/img/pattern.svg') repeat;opacity:0.12}
.hero-inner{display:flex;gap:32px;align-items:center}
.hero-copy{flex:1}
.title{margin:0;font-size:34px;line-height:1.02;color:#073;letter-spacing:-0.01em}
.subtitle{margin:12px 0 18px;color:var(--muted)}
.hero-ctas{display:flex;gap:12px;margin-bottom:8px}
.btn{display:inline-block;padding:10px 18px;border-radius:10px;text-decoration:none;cursor:pointer;border:1px solid transparent}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white;font-weight:600}
.btn.ghost{background:transparent;border:1px solid rgba(0,0,0,0.06)}
.btn.large{padding:14px 22px;font-size:16px}
.hero-art{width:340px;height:220px;flex:0 0 340px;border-radius:16px;overflow:hidden;box-shadow:0 8px 30px rgba(35,56,40,0.08)}
.hero-art .art{width:100%;height:100%}
.meta{color:var(--muted);font-size:13px}

.section-title{font-size:20px;margin:18px 0;color:#0a4}
.social-proof .testimonials{display:flex;gap:16px}
.t{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 6px 18px rgba(10,20,18,0.04);flex:1}
.t cite{display:block;margin-top:8px;color:var(--muted);font-size:13px}

.benefits{padding:20px 0}
.benefit-list{display:flex;gap:18px;list-style:none;padding:0;margin:0}
.benefit-list li{background:var(--card);padding:16px;border-radius:12px;flex:1}

.process{padding:18px 0}
.process-list{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;list-style:none;padding:0}
.process-list li{background:linear-gradient(180deg,#fff,#fbfff9);padding:14px;border-radius:10px}

.faq details{margin-bottom:8px;background:var(--card);padding:12px;border-radius:10px}

.lead{padding:18px 0}
.lead-form{display:grid;grid-template-columns:1fr 240px;gap:8px;align-items:end}
.lead-form input{padding:10px;border-radius:8px;border:1px solid #e6e6e6}
.lead-form label{display:none}
.lead-msg{margin-top:12px;color:var(--accent)}
.small{font-size:12px;color:var(--muted)}

.cta{padding:24px 0;text-align:center}
.site-footer{padding:18px 0;border-top:1px solid rgba(0,0,0,0.04);margin-top:30px}
.site-footer p{margin:0;color:var(--muted);font-size:13px}
.footer-nav{display:flex;gap:12px;margin-top:8px}
.footer-nav a{color:var(--muted);text-decoration:none}

@media (max-width:820px){
  .nav{display:none;position:absolute;right:20px;top:64px;background:rgba(255,255,255,0.98);flex-direction:column;padding:10px;border-radius:10px;box-shadow:0 8px 30px rgba(0,0,0,0.06)}
  .nav.open{display:flex}
  .nav-toggle{display:block;margin-left:auto}
  .hero-inner{flex-direction:column}
  .hero-art{width:100%;height:180px}
  .process-list{grid-template-columns:1fr}
  .lead-form{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Minimal interactions: nav toggle, lead capture
  var navToggle = document.getElementById('navToggle');
  var nav = document.getElementById('nav');
  if(navToggle){
    navToggle.addEventListener('click',function(){
      nav.classList.toggle('open');
    });
  }

  var leadForm = document.getElementById('leadForm');
  var leadMsg = document.getElementById('leadMsg');
  if(leadForm){
    leadForm.addEventListener('submit',function(e){
      e.preventDefault();
      var name = (leadForm.name.value||'').trim();
      var email = (leadForm.email.value||'').trim();
      if(!email){
        leadMsg.textContent = 'Please enter a valid email.';
        return;
      }
      // Simulate capture — store locally and show gentle message
      try{
        var leads = JSON.parse(localStorage.getItem('leads')||'[]');
        leads.push({name:name,email:email,date:new Date().toISOString()});
        localStorage.setItem('leads',JSON.stringify(leads));
      }catch(err){/* ignore */}
      leadForm.reset();
      leadMsg.textContent = 'Thank you. We\'ll send the guide and details about upcoming series.';
    });
  }

  // Smooth links for anchors
  document.addEventListener('click',function(e){
    var a = e.target.closest('a');
    if(!a) return;
    var href = a.getAttribute('href')||'';
    if(href.startsWith('#')){
      var el = document.querySelector(href);
      if(el){
        e.preventDefault();
        el.scrollIntoView({behavior:'smooth',block:'start'});
      }
    }
  });
})();
"} 
